impl<A: SessionFsmUnicastActions + 'static> SessionFsmUnicastPolicy<A> {
    const fn build(session_id: &'static str, actions: A) -> Self {
        Self {
            actions,
            session_id,
        }
    }

    /// docs/adr/0038: the compile-time refusal of a host that only simulates the
    /// duties this machine states. Evaluated where a machine is built with a
    /// host type, so a recorder or a test double does not reach production
    /// by accident; build one on purpose with
    /// [`Self::new_simulated_with_session_id`].
    const HOST_PERFORMS_DUTIES: () = assert!(
        A::REALIZATION.is_performing(),
        "this machine states a duty and its host declares REALIZATION = Simulates: \
         build it with a `_simulated` constructor to run it on a test double on purpose"
    );


    /// Build the machine under the session id its host gives: the host's own
    /// name for the machine, say, or a fixed id a test holds a saved text to
    /// (docs/adr/0045, "Questions the owner answered" 2). `_sessionid` is bound
    /// here and kept until the session ends; a restore binds the saved id in
    /// its place, since the session carries on.
    /// A host whose `REALIZATION` is `Simulates` does not compile here.
    ///
    /// A `no_std` target has no source of randomness the runtime reads, and
    /// takes the id from its host as it takes the time: here, or already
    /// proven through
    /// [`new_with_checked_session_id`](Self::new_with_checked_session_id). The
    /// id is held, not copied.
    ///
    /// # Errors
    ///
    /// An id that is not an XML Nmtoken (the empty text, a space, a `#`) is
    /// refused with the reason, and no machine is built.
    pub fn new_with_session_id(session_id: &'static str, actions: A) -> Result<Self, ::sce_rust_runtime::helpers::session_id::SessionIdRefusal> {
        let () = Self::HOST_PERFORMS_DUTIES;
        Ok(Self::build(::sce_rust_runtime::helpers::session_id::checked(session_id)?, actions))
    }

    /// [`new_with_session_id`](Self::new_with_session_id) with a host that only
    /// simulates its duties — a recorder, a test double — as the caller's
    /// statement that it means to.
    ///
    /// # Errors
    ///
    /// As [`new_with_session_id`](Self::new_with_session_id).
    pub fn new_simulated_with_session_id(session_id: &'static str, actions: A) -> Result<Self, ::sce_rust_runtime::helpers::session_id::SessionIdRefusal> {
        Ok(Self::build(::sce_rust_runtime::helpers::session_id::checked(session_id)?, actions))
    }

    /// [`new_with_session_id`](Self::new_with_session_id) under an id already
    /// proven to be an XML Nmtoken (docs/adr/0073), so nothing is refused. With
    /// the id written as `sce_rust_runtime::session_id!("...")`, a bad one is a
    /// compile error and the program carries no run-time check of it.
    /// A host whose `REALIZATION` is `Simulates` does not compile here.
    pub fn new_with_checked_session_id(session_id: ::sce_rust_runtime::helpers::session_id::SessionId, actions: A) -> Self {
        let () = Self::HOST_PERFORMS_DUTIES;
        Self::build(session_id.as_str(), actions)
    }

    /// [`new_with_checked_session_id`](Self::new_with_checked_session_id) with a
    /// host that only simulates its duties — a recorder, a test double — as the
    /// caller's statement that it means to.
    pub fn new_simulated_with_checked_session_id(session_id: ::sce_rust_runtime::helpers::session_id::SessionId, actions: A) -> Self {
        Self::build(session_id.as_str(), actions)
    }

    /// [`new_with_session_id`](Self::new_with_session_id), in a constant
    /// expression: the machine a program keeps in a `static`, with
    /// `Engine::new_const`, so that nothing is built at start-up and no copy of
    /// it is made on a stack.
    /// A host whose `REALIZATION` is `Simulates` does not compile here.
    ///
    /// # Panics
    ///
    /// At compile time, when the id is not an XML Nmtoken (the empty text, a
    /// space, a `#`): a `static` holding such an id does not build. The reason
    /// is the one `new_with_session_id` gives for the same id.
    pub const fn new_const(session_id: &'static str, actions: A) -> Self {
        let () = Self::HOST_PERFORMS_DUTIES;
        Self::build(::sce_rust_runtime::helpers::session_id::SessionId::new(session_id).as_str(), actions)
    }

    /// [`new_const`](Self::new_const) with a host that only simulates its duties
    /// — a recorder, a test double — as the caller's statement that it means to.
    pub const fn new_simulated_const(session_id: &'static str, actions: A) -> Self {
        Self::build(::sce_rust_runtime::helpers::session_id::SessionId::new(session_id).as_str(), actions)
    }

    /// W3C SCXML G.7: the host the `<sce:action>` operations are dispatched
    /// to — read back, e.g. a recording host's calls, since the machine owns it.
    pub fn actions(&self) -> &A {
        &self.actions
    }




}


